contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target, uint _value, bytes memory _data) public payable {
        require(_value > address(c).balance, "value must exceed C's balance");

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(_target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(!reverted && balAfter == balBefore && depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

